(()=>{"use strict";const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])),en=()=>document.documentElement.lang==="en"||document.documentElement.dir==="ltr",t=(h,e)=>en()?e:h;
async function api(p,o={}){const i={credentials:"same-origin",...o,headers:{...(o.headers||{})}};if(o.body&&!(o.body instanceof FormData)){i.headers["Content-Type"]="application/json";i.body=JSON.stringify(o.body)}let r;try{r=await fetch(p,i)}catch(e){throw new Error(window.GmachDescribeNetworkError?window.GmachDescribeNetworkError(e):t("לא ניתן להתחבר לשרת","Could not connect to the server"))}const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(window.GmachDescribeHttpError?window.GmachDescribeHttpError(r,d):(d.error||t("הפעולה נכשלה","Action failed")));return d}function dlg(id,title){let d=$("#"+id);if(!d){d=document.createElement("dialog");d.id=id;d.className="modal modal-wide";document.body.append(d)}d.innerHTML='<button class="dialog-close">×</button><h2>'+esc(title)+'</h2><div class="privacy-availability-body"></div>';$(".dialog-close",d).onclick=()=>d.close();return d}function toast(s,b=false){if(window.GmachToast)return window.GmachToast(s,b?"error":"success");}
const LEGACY_AVAILABILITY_LABEL="ניהול זמינות מתקדם";
function ruleTypeLabel(type){return({closure:t("סגירה בתאריך מסוים","Date closure"),weekly_window:t("שעות פעילות מיוחדות","Special weekly hours"),preparation:t("זמן הכנה","Preparation time"),advance_limit:t("כמה זמן מראש אפשר להזמין","How far ahead users can book")})[type]||type}
function ruleDescription(r){
 const x=r.rule||{};
 if(r.rule_type==="closure")return t("סגור מ־","Closed from ")+new Date(x.startsAt).toLocaleString(en()?"en-GB":"he-IL")+t(" עד "," to ")+new Date(x.endsAt).toLocaleString(en()?"en-GB":"he-IL")+(x.reason?" · "+x.reason:"");
 if(r.rule_type==="weekly_window"){const days=(x.days||[]).map(n=>[t("א׳","Sun"),t("ב׳","Mon"),t("ג׳","Tue"),t("ד׳","Wed"),t("ה׳","Thu"),t("ו׳","Fri"),t("שבת","Sat")][n]).join(", ");return days+" · "+esc(x.start||"")+"–"+esc(x.end||"")+(x.label?" · "+esc(x.label):"")}
 if(r.rule_type==="preparation")return t("נדרש זמן הכנה של ","Preparation time: ")+Number(x.minutes||0)+" "+t("דקות","minutes");
 if(r.rule_type==="advance_limit")return t("אפשר להזמין עד ","Book up to ")+Number(x.days||0)+" "+t("ימים מראש","days ahead");
 return "";
}
function ruleFields(type){
 if(type==="closure")return '<div class="pa-rule-fields"><div class="two-columns"><label>'+t("סגור מ־","Closed from")+'<input name="startsAt" type="datetime-local" required></label><label>'+t("עד","Until")+'<input name="endsAt" type="datetime-local" required></label></div><label>'+t("סיבה, רשות","Reason, optional")+'<input name="reason" maxlength="300" placeholder="'+t("למשל: חופשה","e.g. holiday")+'"></label></div>';
 if(type==="weekly_window"){const dayNames=[[0,t("ראשון","Sunday")],[1,t("שני","Monday")],[2,t("שלישי","Tuesday")],[3,t("רביעי","Wednesday")],[4,t("חמישי","Thursday")],[5,t("שישי","Friday")],[6,t("שבת","Saturday")]];return '<div class="pa-rule-fields"><label>'+t("ימים","Days")+'<span class="pa-days">'+dayNames.map(([v,n])=>'<label><input type="checkbox" name="days" value="'+v+'">'+n+'</label>').join("")+'</span></label><div class="two-columns"><label>'+t("משעה","From")+'<input name="start" type="time" required></label><label>'+t("עד שעה","Until")+'<input name="end" type="time" required></label></div><label>'+t("הערה, רשות","Label, optional")+'<input name="label" maxlength="120"></label></div>'}
 if(type==="preparation")return '<div class="pa-rule-fields"><label>'+t("כמה דקות הכנה נדרשות לפני איסוף?","Preparation minutes before pickup")+'<input name="minutes" type="number" min="0" max="10080" value="60" required></label></div>';
 return '<div class="pa-rule-fields"><label>'+t("כמה ימים מראש אפשר להזמין?","How many days ahead can users book?")+'<input name="daysAhead" type="number" min="1" max="1095" value="30" required></label></div>';
}
function readRule(form,type){
 if(type==="closure")return{startsAt:form.startsAt.value,endsAt:form.endsAt.value,reason:form.reason.value||null};
 if(type==="weekly_window")return{days:[...form.querySelectorAll('input[name="days"]:checked')].map(x=>Number(x.value)),start:form.start.value,end:form.end.value,label:form.label.value||null};
 if(type==="preparation")return{minutes:Number(form.minutes.value||0)};
 return{days:Number(form.daysAhead.value||1)};
}
async function openAvailability(){
 const d=dlg("availability-rules-dialog",t("חסימות וזמינות מיוחדת","Closures & special availability")),b=$(".privacy-availability-body",d);d.showModal();
 let orgs=[];try{const snap=await api("/api/me/dashboard");orgs=snap.organizations||[]}catch(e){b.textContent=e.message||t("לא ניתן לטעון גמ״חים","Could not load gmachs");return}
 if(!orgs.length){b.innerHTML="<p>"+t("אין גמ״חים לניהול.","No gmachs to manage.")+"</p>";return}
 b.innerHTML='<p class="availability-explainer">'+t("כאן מגדירים רק חריגים לשעות הרגילות: סגירה בתאריך מסוים, שעות שונות בימים קבועים, זמן הכנה או מגבלת הזמנה מראש. אם אין צורך בחריגים — לא צריך להגדיר כאן דבר.","Use this only for exceptions to your normal hours: a closure, special weekly hours, preparation time, or an advance-booking limit. If you do not need exceptions, you can leave this empty.")+'</p><label>'+t("גמ״ח","Gmach")+'<select id="pa-org">'+orgs.map(o=>'<option value="'+esc(o.id)+'">'+esc(o.name)+'</option>').join("")+'</select></label><div id="pa-rules"></div>';
 const sel=$("#pa-org",d),host=$("#pa-rules",d);
 async function load(){
  const x=await api("/api/organizations/"+encodeURIComponent(sel.value)+"/availability-rules");
  host.innerHTML='<form id="pa-create" class="form-grid"><label>'+t("מה תרצו להגדיר?","What would you like to set?")+'<select name="type"><option value="closure">'+t("סגירה בתאריך מסוים","Date closure")+'</option><option value="weekly_window">'+t("שעות פעילות מיוחדות","Special weekly hours")+'</option><option value="preparation">'+t("זמן הכנה לפני איסוף","Preparation time")+'</option><option value="advance_limit">'+t("מגבלת הזמנה מראש","Advance booking limit")+'</option></select></label><label>'+t("סניף, רשות","Branch, optional")+'<select name="branch"><option value="">'+t("כל הסניפים","All branches")+'</option>'+(x.branches||[]).map(v=>'<option value="'+esc(v.id)+'">'+esc(v.name)+'</option>').join("")+'</select></label><label>'+t("פריט, רשות","Item, optional")+'<select name="item"><option value="">'+t("כל הפריטים","All items")+'</option>'+(x.items||[]).map(v=>'<option value="'+esc(v.id)+'">'+esc(v.title)+'</option>').join("")+'</select></label><div data-rule-fields>'+ruleFields("closure")+'</div><button class="button button-primary">'+t("שמירת החריג","Save rule")+'</button></form><div style="display:grid;gap:8px;margin-top:16px">'+(x.rules||[]).map(r=>'<article class="dashboard-row"><div><strong>'+esc(ruleTypeLabel(r.rule_type))+'</strong><p class="pa-rule-preview">'+ruleDescription(r)+'</p><small>'+(r.active?t("פעיל","Active"):t("כבוי","Disabled"))+'</small></div><div class="dashboard-row-actions"><button class="button button-secondary button-small" data-rule-toggle="'+esc(r.id)+'" data-active="'+(r.active?"1":"0")+'">'+(r.active?t("השבתה","Disable"):t("הפעלה","Enable"))+'</button><button class="button button-danger button-small" data-rule-delete="'+esc(r.id)+'">'+t("מחיקה","Delete")+'</button></div></article>').join("")+'</div>';
  const form=$("#pa-create",d),typeSelect=form.type,fields=$("[data-rule-fields]",form);
  typeSelect.onchange=()=>{fields.innerHTML=ruleFields(typeSelect.value)};
  form.onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;try{const rule=readRule(f,f.type.value);await api("/api/organizations/"+encodeURIComponent(sel.value)+"/availability-rules",{method:"POST",body:{type:f.type.value,branchId:f.branch.value||null,itemId:f.item.value||null,rule}});toast(t("החריג נשמר","Rule saved"));await load()}catch(err){toast(err.message,true)}};
  $$("[data-rule-toggle]",d).forEach(x=>x.onclick=async()=>{try{await api("/api/availability-rules/"+encodeURIComponent(x.dataset.ruleToggle),{method:"PATCH",body:{active:x.dataset.active!=="1"}});await load()}catch(e){toast(e.message,true)}});
  $$("[data-rule-delete]",d).forEach(x=>x.onclick=async()=>{if(!confirm(t("למחוק את כלל הזמינות?","Delete this availability rule?")))return;try{await api("/api/availability-rules/"+encodeURIComponent(x.dataset.ruleDelete),{method:"DELETE",body:{}});await load()}catch(e){toast(e.message,true)}})
 }
 sel.onchange=load;await load()
}
async function openPrivacyAdmin(){const d=dlg("privacy-requests-admin",t("בקשות פרטיות","Privacy requests")),b=$(".privacy-availability-body",d);d.showModal();async function load(){try{const x=await api("/api/admin/data-requests");b.innerHTML=(x.requests||[]).map(r=>'<article class="dashboard-row"><div><strong>'+esc(r.request_type)+' · '+esc(r.full_name)+'</strong><p>'+esc(r.details||"")+'</p><small>'+esc(r.email)+' · '+esc(r.status)+' · '+esc(r.created_at)+'</small></div><div class="dashboard-row-actions"><select data-privacy-status="'+esc(r.id)+'">'+["open","processing","completed","rejected"].map(s=>'<option '+(s===r.status?"selected":"")+'>'+s+'</option>').join("")+'</select><button class="button button-secondary button-small" data-privacy-save="'+esc(r.id)+'">'+t("עדכון","Update")+'</button></div></article>').join("")||"<p>"+t("אין בקשות פתוחות.","No requests.")+"</p>";$$("[data-privacy-save]",d).forEach(btn=>btn.onclick=async()=>{const status=$('[data-privacy-status="'+CSS.escape(btn.dataset.privacySave)+'"]',d).value,note=prompt(t("הערת מנהל, רשות","Admin note, optional"))||"";try{await api("/api/admin/data-requests/"+encodeURIComponent(btn.dataset.privacySave),{method:"PATCH",body:{status,adminNote:note}});toast(t("הבקשה עודכנה","Request updated"));await load()}catch(e){toast(e.message,true)}})}catch(e){b.innerHTML='<p role="alert">'+esc(e.message)+'</p>'}}await load()}
function install(){const a=$("#dashboard-view .dashboard-actions");if(a&&!a.querySelector("[data-availability-rules]")){const b=document.createElement("button");b.type="button";b.className="button button-secondary";b.dataset.availabilityRules="1";b.textContent=t("חסימות וזמינות מיוחדת","Closures & special availability");b.onclick=openAvailability;a.prepend(b)}const tab=$("#admin-tab");if(tab&&!tab.hidden&&a&&!a.querySelector("[data-privacy-admin]")){const b=document.createElement("button");b.type="button";b.className="button button-secondary";b.dataset.privacyAdmin="1";b.textContent=t("בקשות פרטיות","Privacy requests");b.onclick=openPrivacyAdmin;a.prepend(b)}}function init(){const o=new MutationObserver(install);o.observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:["hidden","lang","dir"]});install()}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init,{once:true});else init()})();